insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000481011', '40000000-0000-4000-8000-000000048101', 'Faça primeiro um pequeno registro das grandezas conhecidas e daquilo que a pergunta realmente pede.', 1), ('60000000-0000-4000-8000-000000481012', '40000000-0000-4000-8000-000000048101', 'Multiplique componentes correspondentes.', 2), ('60000000-0000-4000-8000-000000481013', '40000000-0000-4000-8000-000000048101', 'Some os três produtos, preservando o sinal negativo.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048101', '$u \cdot v=2$.', 'Trate as coordenadas como informações de posição: alinhar cada eixo antes de operar evita conclusões visuais enganosas. O produto escalar combina componentes correspondentes e produz um número real. Ele conecta a álgebra à geometria por meio de ortogonalidade, ângulos, projeções e trabalho; por isso conferimos também o significado do resultado. A alternativa A coincide com a relação obtida; a alternativa B ($4$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
