insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048116', '$90^\circ$.', 'Trate as coordenadas como informações de posição: alinhar cada eixo antes de operar evita conclusões visuais enganosas. O produto escalar combina componentes correspondentes e produz um número real. Ele conecta a álgebra à geometria por meio de ortogonalidade, ângulos, projeções e trabalho; por isso conferimos também o significado do resultado. A alternativa A coincide com a relação obtida; a alternativa B ($0^\circ$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000481161', '40000000-0000-4000-8000-000000048116', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000481162', '40000000-0000-4000-8000-000000048116', 'Calcule o produto', '$u \cdot v=0.$', 2), ('70000000-0000-4000-8000-000000481163', '40000000-0000-4000-8000-000000048116', 'Use a relação angular', '$u \cdot v=|u||v|\cos \theta.$', 3), ('70000000-0000-4000-8000-000000481164', '40000000-0000-4000-8000-000000048116', 'Conclua', '$\cos \theta=0 \Rightarrow \theta=90^\circ.$', 4), ('70000000-0000-4000-8000-000000481165', '40000000-0000-4000-8000-000000048116', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
