insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048126', '$u \times v=(0,0,2)$.', 'Trate as coordenadas como informações de posição: alinhar cada eixo antes de operar evita conclusões visuais enganosas. O produto vetorial produz um vetor perpendicular aos dois fatores, com sentido determinado pela regra da mão direita. Seu módulo também mede a área do paralelogramo; o produto misto acrescenta um terceiro vetor e mede volume orientado. A alternativa A coincide com a relação obtida; a alternativa B ($(0,0,-2)$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
