insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000481281', '40000000-0000-4000-8000-000000048128', 'Ao final, pergunte se o sinal, a direção ou a dimensão do resultado fazem sentido para a situação.', 1), ('60000000-0000-4000-8000-000000481282', '40000000-0000-4000-8000-000000048128', 'Use a orientação positiva dos eixos coordenados.', 2), ('60000000-0000-4000-8000-000000481283', '40000000-0000-4000-8000-000000048128', 'O produto do eixo x pelo eixo y aponta para o eixo z.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048128', '$u \times v=(0,0,12)$.', 'O resultado deve respeitar tanto a definição algébrica quanto a interpretação geométrica do objeto em três dimensões. O produto vetorial produz um vetor perpendicular aos dois fatores, com sentido determinado pela regra da mão direita. Seu módulo também mede a área do paralelogramo; o produto misto acrescenta um terceiro vetor e mede volume orientado. A alternativa A coincide com a relação obtida; a alternativa B ($(0,0,-12)$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000481281', '40000000-0000-4000-8000-000000048128', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000481282', '40000000-0000-4000-8000-000000048128', 'Monte o determinante', 'As duas primeiras direções são os eixos x e y.', 2), ('70000000-0000-4000-8000-000000481283', '40000000-0000-4000-8000-000000048128', 'Calcule o módulo', '$3 \cdot4=12.$', 3), ('70000000-0000-4000-8000-000000481284', '40000000-0000-4000-8000-000000048128', 'Defina o sentido', 'Pela regra da mão direita, o resultado aponta para z positivo.', 4), ('70000000-0000-4000-8000-000000481285', '40000000-0000-4000-8000-000000048128', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
