insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000481441', '40000000-0000-4000-8000-000000048144', 'Não tente calcular tudo de uma vez: destaque primeiro a propriedade que caracteriza o problema.', 1), ('60000000-0000-4000-8000-000000481442', '40000000-0000-4000-8000-000000048144', 'O volume é o valor absoluto do produto misto.', 2), ('60000000-0000-4000-8000-000000481443', '40000000-0000-4000-8000-000000048144', 'Como os vetores estão nos eixos, o determinante é o produto das entradas não nulas.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048144', '$V=24$.', 'A notação compacta não substitui o raciocínio: identificar o tipo de objeto é o passo que determina qual fórmula usar. O produto vetorial produz um vetor perpendicular aos dois fatores, com sentido determinado pela regra da mão direita. Seu módulo também mede a área do paralelogramo; o produto misto acrescenta um terceiro vetor e mede volume orientado. A alternativa A coincide com a relação obtida; a alternativa B ($12$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
