insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000481491', '40000000-0000-4000-8000-000000048149', 'Não tente calcular tudo de uma vez: destaque primeiro a propriedade que caracteriza o problema.', 1), ('60000000-0000-4000-8000-000000481492', '40000000-0000-4000-8000-000000048149', 'O volume é o valor absoluto do produto misto.', 2), ('60000000-0000-4000-8000-000000481493', '40000000-0000-4000-8000-000000048149', 'Como os vetores estão nos eixos, o determinante é o produto das entradas não nulas.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048149', '$V=720$.', 'A notação compacta não substitui o raciocínio: identificar o tipo de objeto é o passo que determina qual fórmula usar. O produto vetorial produz um vetor perpendicular aos dois fatores, com sentido determinado pela regra da mão direita. Seu módulo também mede a área do paralelogramo; o produto misto acrescenta um terceiro vetor e mede volume orientado. A alternativa A coincide com a relação obtida; a alternativa B ($360$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000481491', '40000000-0000-4000-8000-000000048149', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000481492', '40000000-0000-4000-8000-000000048149', 'Monte o produto misto', '$V=|(u \times v) \cdot w|.$', 2), ('70000000-0000-4000-8000-000000481493', '40000000-0000-4000-8000-000000048149', 'Use a estrutura diagonal', '$V=|8 \cdot9 \cdot10|.$', 3), ('70000000-0000-4000-8000-000000481494', '40000000-0000-4000-8000-000000048149', 'Calcule', '$V=720.$', 4), ('70000000-0000-4000-8000-000000481495', '40000000-0000-4000-8000-000000048149', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000048150', '20000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000223', 'multiple_choice', 'medium', 'published', 'Para validar um resultado de laboratório de geometria analítica, resolva: identifique o volume do paralelepípedo gerado por $u=(9,0,0)$, $v=(0,10,0)$ e $w=(0,0,11)$?') on conflict (id) do update set subject_id = excluded.subject_id, source_id = excluded.source_id, kind = excluded.kind, difficulty = excluded.difficulty, publication_status = excluded.publication_status, statement_markdown = excluded.statement_markdown;
