insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000481501', '40000000-0000-4000-8000-000000048150', 'Escolha uma alternativa apenas depois de comparar o resultado final com cada possibilidade, incluindo o sinal.', 1), ('60000000-0000-4000-8000-000000481502', '40000000-0000-4000-8000-000000048150', 'O volume é o valor absoluto do produto misto.', 2), ('60000000-0000-4000-8000-000000481503', '40000000-0000-4000-8000-000000048150', 'Como os vetores estão nos eixos, o determinante é o produto das entradas não nulas.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048150', '$V=990$.', 'A resolução fica mais segura quando cada transformação é justificada e o resultado é verificado no enunciado original. O produto vetorial produz um vetor perpendicular aos dois fatores, com sentido determinado pela regra da mão direita. Seu módulo também mede a área do paralelogramo; o produto misto acrescenta um terceiro vetor e mede volume orientado. A alternativa A coincide com a relação obtida; a alternativa B ($495$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000481501', '40000000-0000-4000-8000-000000048150', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000481502', '40000000-0000-4000-8000-000000048150', 'Monte o produto misto', '$V=|(u \times v) \cdot w|.$', 2), ('70000000-0000-4000-8000-000000481503', '40000000-0000-4000-8000-000000048150', 'Use a estrutura diagonal', '$V=|9 \cdot10 \cdot11|.$', 3), ('70000000-0000-4000-8000-000000481504', '40000000-0000-4000-8000-000000048150', 'Calcule', '$V=990.$', 4), ('70000000-0000-4000-8000-000000481505', '40000000-0000-4000-8000-000000048150', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
